package com.enterprise.domain.port;

public interface FindUserQuery {
    User findById(Long id);
}

package com.enterprise.domain.usecase;

import com.enterprise.domain.port.FindUserQuery;

public class GetUserProfileUseCase {
    private final FindUserQuery findUserQuery;

    public GetUserProfileUseCase(FindUserQuery findUserQuery) {
        this.findUserQuery = findUserQuery;
    }

    public UserProfile execute(Long userId) {
        User user = findUserQuery.findById(userId);
        if (user == null) {
            throw new UserNotFoundException(userId);
        }
        return new UserProfile(user.getName(), user.getEmail());
    }
}
